1: import { useMemo } from 'react';
2: import useSWR from 'swr';
3: import { openmrsFetch, restBaseUrl, useConfig } from '@openmrs/esm-framework';
4: import { type ConfigObject } from '../config-schema';
5: 
6: const stickyNoteRepresentation =
7:   'custom:(uuid,value,obsDatetime,encounter:(uuid),formNamespaceAndPath,auditInfo:(creator:(display)))';
8: 
9: export interface StickyNoteObs {
10:   uuid: string;
11:   value: string;
12:   obsDatetime: string;
13:   encounter?: { uuid: string } | null;
14:   formNamespaceAndPath?: string | null;
15:   auditInfo?: {
16:     creator?: {
17:       display?: string;
18:     };
19:   };
20: }
21: 
22: interface StickyNoteResponse {
23:   results: Array<StickyNoteObs>;
24: }
25: 
26: // Exclude obs attached to an encounter or created by a form engine. The sticky-note UI only
27: // writes standalone obs, so this guards against another feature (e.g. the visit note) writing
28: // to the same concept UUID.
29: export const isStandaloneStickyNote = (obs: StickyNoteObs) => !obs.encounter && !obs.formNamespaceAndPath;
30: 
31: export const useStickyNote = (patientUuid: string) => {
32:   const { stickyNoteConceptUuid } = useConfig<ConfigObject>();
33:   const url =
34:     patientUuid && stickyNoteConceptUuid
35:       ? `${restBaseUrl}/obs?patient=${patientUuid}&concept=${stickyNoteConceptUuid}&v=${stickyNoteRepresentation}`
36:       : null;
37: 
38:   const { data, error, isLoading, mutate } = useSWR<{ data: StickyNoteResponse }, Error>(url, openmrsFetch);
39: 
40:   const note = useMemo(
41:     () =>
42:       data?.data?.results
43:         ?.filter(isStandaloneStickyNote)
44:         .slice()
45:         .sort((a, b) => new Date(b.obsDatetime).getTime() - new Date(a.obsDatetime).getTime())[0],
46:     [data?.data?.results],
47:   );
48: 
49:   return {
50:     note,
51:     isLoading,
52:     error,
53:     mutate,
54:   };
55: };
56: 
57: export const createStickyNote = (patientUuid: string, value: string, conceptUuid: string) => {
58:   return openmrsFetch(`${restBaseUrl}/obs`, {
59:     method: 'POST',
60:     headers: { 'Content-Type': 'application/json' },
61:     body: JSON.stringify({
62:       person: patientUuid,
63:       concept: conceptUuid,
64:       value,
65:       obsDatetime: new Date().toISOString(),
66:     }),
67:   });
68: };
